import React from 'react';
import { formatCurrency, formatPercent } from '../../utils/format';

export default function TickerTape({ listings = [] }) {
  if (!listings.length) return null;
  // Duplicate for seamless loop
  const items = [...listings.slice(0, 20), ...listings.slice(0, 20)];

  return (
    <div style={{
      background: 'var(--bg-void,#04070d)',
      borderBottom: '1px solid var(--border,#1a2840)',
      overflow: 'hidden', padding: '7px 0',
      position: 'relative',
    }}>
      {/* Fade edges */}
      <div style={{ position: 'absolute', left: 0, top: 0, bottom: 0, width: 80, zIndex: 2, background: 'linear-gradient(90deg, var(--bg-primary,#060b14), transparent)', pointerEvents: 'none' }} />
      <div style={{ position: 'absolute', right: 0, top: 0, bottom: 0, width: 80, zIndex: 2, background: 'linear-gradient(-90deg, var(--bg-primary,#060b14), transparent)', pointerEvents: 'none' }} />

      <div style={{
        display: 'flex',
        animation: 'tickerScroll 50s linear infinite',
        width: 'max-content',
      }}>
        {items.map((coin, i) => {
          const up = coin.change24h >= 0;
          return (
            <div key={i} style={{
              display: 'flex', alignItems: 'center', gap: 8,
              padding: '0 20px',
              borderRight: '1px solid rgba(255,255,255,0.04)',
              cursor: 'default',
            }}>
              <img src={coin.logo} alt={coin.symbol} width={16} height={16}
                style={{ borderRadius: '50%', flexShrink: 0 }}
                onError={e => e.target.style.display = 'none'} />
              <span style={{ fontSize: 11, fontWeight: 700, color: 'var(--text-secondary,#7b94b8)', fontFamily: 'JetBrains Mono,monospace', letterSpacing: '0.5px' }}>
                {coin.symbol}
              </span>
              <span style={{ fontSize: 11, color: 'var(--text-primary,#eef2fa)', fontFamily: 'JetBrains Mono,monospace' }}>
                {formatCurrency(coin.price)}
              </span>
              <span style={{
                fontSize: 10, fontWeight: 700,
                fontFamily: 'JetBrains Mono,monospace',
                color: up ? '#00e5b3' : '#f03e55',
                background: up ? 'rgba(0,229,179,0.08)' : 'rgba(240,62,85,0.08)',
                padding: '1px 5px', borderRadius: 4,
              }}>
                {up ? '▲' : '▼'} {Math.abs(coin.change24h).toFixed(2)}%
              </span>
            </div>
          );
        })}
      </div>

      <style>{`
        @keyframes tickerScroll {
          0%   { transform: translateX(0); }
          100% { transform: translateX(-50%); }
        }
      `}</style>
    </div>
  );
}
